import { useEffect, useState } from 'react';
import { Animated, Platform, type ViewProps } from 'react-native';

import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { cn } from '@/lib/utils';

interface SkeletonProps extends ViewProps {
  className?: string;
  /** Set false for a static placeholder (e.g. in tests/snapshots). */
  animated?: boolean;
}

// The native animated driver is unavailable on react-native-web (it warns and
// falls back to JS); opacity animates fine on the JS driver there.
const isWeb = Platform.OS === 'web';

/** Placeholder block for loading states, with a gentle pulse. */
export function Skeleton({ className, animated = true, style, ...props }: SkeletonProps) {
  const [opacity] = useState(() => new Animated.Value(0.5));
  // Respect the OS "Reduce Motion" setting — render a still placeholder.
  const reducedMotion = useReducedMotion();
  const shouldAnimate = animated && !reducedMotion;

  useEffect(() => {
    if (!shouldAnimate) return;
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(opacity, { toValue: 1, duration: 700, useNativeDriver: !isWeb }),
        Animated.timing(opacity, { toValue: 0.5, duration: 700, useNativeDriver: !isWeb }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [shouldAnimate, opacity]);

  return (
    <Animated.View
      className={cn('rounded-md bg-muted', className)}
      style={[shouldAnimate ? { opacity } : null, style]}
      {...props}
    />
  );
}
